INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q3403823', 'Capture of Gorée', 'The capture of Gorée occurred in December 1758 when a British naval expedition led by Augustus Keppel against the French island of Gorée off the coast of Senegal during the Seven Years'' War. Keppel bombarded the fortress and then landed his marines to take possession.', 1758, 12, NULL, NULL, NULL, NULL, 'month', 'December 1758', 34, 'https://en.wikipedia.org/wiki/Capture_of_Gor%C3%A9e'),
  ('Q5037057', 'Capture of Senegal', 'The British capture of Senegal took place in 1758 during the Seven Years'' War with France, as part of a concerted British strategy to weaken the French economy by damaging her international trade. To this end, a succession of small British military expeditions landed in Senegal and captured Gorée and Fort Saint Louis, the French slave fort located at Saint-Louis, seizing French vessels and supplies.', 1758, NULL, NULL, NULL, NULL, NULL, 'year', '1758', 34, 'https://en.wikipedia.org/wiki/British_capture_of_Senegal'),
  ('Q106880868', 'Battle of Leybar Bridge', 'The Battle of Leybar Bridge was fought on 21 April 1855 between the Trarza army of Mohammed al-Habib and the French garrison of the tower on Leybar Bridge, outside of Saint-Louis in the French colony of Senegal, during the Second Franco-Trarza War.', 1855, 4, 21, NULL, NULL, NULL, 'day', '21 April 1855', 34, 'https://en.wikipedia.org/wiki/Battle_of_Leybar_Bridge'),
  ('Q2889150', 'Battle of Logandème', 'The Battle of Logandème (18 May 1859) was an uprising led by the Serer King Maad a Sinig Kumba Ndoffene Famak Joof, king of Sine, against the French Empire. The battle took place at Logandème (in Fatick) which was a part of Sine at the time.', 1859, 5, 18, NULL, NULL, NULL, 'day', '18 May 1859', 34, 'https://en.wikipedia.org/wiki/Battle_of_Logand%C3%A8me'),
  ('Q696829', 'Battle of Dakar', 'The Battle of Dakar, also known as Operation Menace, was an unsuccessful attempt in September 1940 by the Allies to capture the strategic port of Dakar in French West Africa (modern-day Senegal). It was hoped that the success of the operation could overthrow the pro-German Vichy French administration in the colony, and be replaced by a pro-Allied Free French one under General Charles de Gaulle.', 1940, 9, 23, 1940, 9, 25, 'day', '23 September 1940 – 25 September 1940', 61, 'https://en.wikipedia.org/wiki/Battle_of_Dakar'),
  ('Q303059', 'Thiaroye Massacre', 'The Thiaroye massacre was a massacre of black African soldiers serving in French West Africa, committed by the French Army on the morning of 1 December 1944 near Dakar, French Senegal. Those killed were members of the Tirailleurs Sénégalais, and were veterans of the 1940 Battle of France who had been recently liberated from prison camps in Europe.', 1944, 12, 1, NULL, NULL, NULL, 'day', '1 December 1944', 45, 'https://en.wikipedia.org/wiki/Thiaroye_massacre'),
  ('Q209965', 'Casamance conflict', 'The Casamance conflict (French: Conflit en Casamance) is an ongoing low-level conflict that has been waged between the Government of Senegal and the Movement of Democratic Forces of Casamance (MFDC) since 1982. On 1 May 2014, the leader of the MFDC sued for peace and declared a unilateral ceasefire.', 1982, NULL, NULL, 2014, 5, 1, 'year', '1982 – 1 May 2014', 58, 'https://en.wikipedia.org/wiki/Casamance_conflict'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods');

